-- Run once in the Jett Pal Supabase SQL Editor.
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,role text not null default 'Staff',created_at timestamptz not null default now());
create or replace function public.handle_new_jett_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email) on conflict(id) do update set full_name=excluded.full_name,email=excluded.email; return new; end; $$;
drop trigger if exists on_jett_auth_user_created on auth.users;
create trigger on_jett_auth_user_created after insert or update of email,raw_user_meta_data on auth.users for each row execute procedure public.handle_new_jett_user();
insert into public.profiles(id,full_name,email) select id,coalesce(raw_user_meta_data->>'full_name',split_part(email,'@',1)),email from auth.users on conflict(id) do update set full_name=excluded.full_name,email=excluded.email;
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),name text,is_group boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),last_read_at timestamptz,primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id),body text not null check(char_length(body) between 1 and 5000),created_at timestamptz not null default now());
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at desc);
create or replace function public.jett_is_chat_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_members where conversation_id=target and user_id=auth.uid()); $$;
create or replace function public.jett_is_chat_creator(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversations where id=target and created_by=auth.uid()); $$;
alter table public.profiles enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security;
drop policy if exists "Staff can view profiles" on public.profiles; create policy "Staff can view profiles" on public.profiles for select to authenticated using(true);
drop policy if exists "Users update own profile" on public.profiles; create policy "Users update own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists "Members view conversations" on public.conversations; create policy "Members view conversations" on public.conversations for select to authenticated using(public.jett_is_chat_member(id));
drop policy if exists "Users create conversations" on public.conversations; create policy "Users create conversations" on public.conversations for insert to authenticated with check(created_by=auth.uid());
drop policy if exists "Members view membership" on public.conversation_members; create policy "Members view membership" on public.conversation_members for select to authenticated using(public.jett_is_chat_member(conversation_id));
drop policy if exists "Creator adds members" on public.conversation_members; create policy "Creator adds members" on public.conversation_members for insert to authenticated with check(public.jett_is_chat_creator(conversation_id));
drop policy if exists "Users update own read receipt" on public.conversation_members; create policy "Users update own read receipt" on public.conversation_members for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "Creator removes members" on public.conversation_members; create policy "Creator removes members" on public.conversation_members for delete to authenticated using(public.jett_is_chat_creator(conversation_id) or user_id=auth.uid());
drop policy if exists "Members read messages" on public.messages; create policy "Members read messages" on public.messages for select to authenticated using(public.jett_is_chat_member(conversation_id));
drop policy if exists "Members send messages as themselves" on public.messages; create policy "Members send messages as themselves" on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.jett_is_chat_member(conversation_id));
create or replace function public.jett_touch_conversation() returns trigger language plpgsql security definer set search_path=public as $$ begin update public.conversations set updated_at=new.created_at where id=new.conversation_id; return new; end; $$;
drop trigger if exists jett_message_touch_conversation on public.messages; create trigger jett_message_touch_conversation after insert on public.messages for each row execute procedure public.jett_touch_conversation();
do $$ begin alter publication supabase_realtime add table public.messages; exception when duplicate_object then null; end $$;
